#!/bin/bash
# Permanent blacklist orphan fix — run as root on ecs-cc
set -euo pipefail
WEB=/var/www/fusionpbx/app/agent_dashboard
LIVE=/opt/skykin/fs-live
mkdir -p "$LIVE"

echo "==> 1) skykin_bl_sync.php (remove clears all hash keys)"
echo '' | base64 -d > /tmp/skykin_bl_sync.php
docker cp /tmp/skykin_bl_sync.php skykin-web:$WEB/skykin_bl_sync.php

echo "==> 2) skykin_bl_gate.lua (file is authority; auto-clear orphan hash)"
echo '' | base64 -d > /tmp/skykin_bl_gate.lua
docker cp /tmp/skykin_bl_gate.lua skykin-freeswitch:/etc/freeswitch/scripts/skykin_bl_gate.lua
cp /tmp/skykin_bl_gate.lua "$LIVE/skykin_bl_gate.lua"

docker exec skykin-web php -r 'opcache_reset();' 2>/dev/null || true

echo "==> 3) Rebuild hash from DB only"
docker exec skykin-web php -r '
require "/var/www/fusionpbx/app/agent_dashboard/skykin_config.php";
require_once "/var/www/fusionpbx/app/agent_dashboard/skykin_bl_sync.php";
if (!function_exists("skykin_bl_hash_clear_number")) { fwrite(STDERR, "OLD sync still loaded\n"); exit(1); }
skykin_bl_push(skykin_pdo_fusionpbx());
echo "push ok\n";
'

PW=$(grep -E '^ESL_PASSWORD=' /opt/skykin/app/.env | cut -d= -f2-)
FS(){ docker exec skykin-freeswitch fs_cli -H 127.0.0.1 -P 8021 -p "$PW" -x "$1"; }
echo -n "911528271 (must be empty): "; FS "hash select/skykin_bl/ahununu~911528271"
echo -n "946289866 (must be 1): "; FS "hash select/skykin_bl/ahununu~946289866"
grep -n 'orphan hash\|Authority is the blacklist' "$LIVE/skykin_bl_gate.lua" | head -3
echo DONE
